-- Invite codes: one-time codes generated by Admins, plus at most one
-- master code. Nobody writes to the table directly; Admins go through
-- create_invite_codes, revoke_invite_code and set_master_code, and sign-up
-- goes through the auth.users trigger (next migration).

create extension if not exists pgcrypto with schema extensions;

create table public.invite_codes (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  kind text not null check (kind in ('one_time', 'master')),
  -- Nullable: the seeded or hand-inserted master code has no creator
  created_by uuid references public.profiles (id) on delete set null,
  used_by uuid references public.profiles (id) on delete set null,
  used_at timestamptz,
  revoked boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Only one-time codes record a use; the master code is never "used up"
  constraint invite_codes_master_never_used
    check (kind = 'one_time' or (used_by is null and used_at is null))
);

-- At most one master row
create unique index invite_codes_one_master
  on public.invite_codes ((true))
  where kind = 'master';

create trigger invite_codes_updated_at
  before update on public.invite_codes
  for each row execute function public.set_updated_at();

-- Security: Admins can read codes. No insert, update or delete policies,
-- so writes only happen inside the security definer functions below.
alter table public.invite_codes enable row level security;

create policy "Admins can read invite codes"
  on public.invite_codes for select
  to authenticated
  using (public.has_role('admin'));

-- Grants: select only (RLS limits it to Admins; anon has no policy and
-- sees no rows). Revoke first, because Supabase's default privileges
-- would otherwise also grant insert, update, delete and truncate.
revoke all on table public.invite_codes from anon, authenticated;
grant select on table public.invite_codes to anon, authenticated;
grant all on table public.invite_codes to service_role;

-- Admin only. Generates `count` one-time codes of 12 random characters and
-- returns them. The alphabet has 32 characters (no I, O, 0 or 1, which are
-- easy to misread), so each random byte maps to one character without bias.
create function public.create_invite_codes(count int)
returns setof text
language plpgsql
security definer
set search_path = ''
as $$
declare
  c_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_bytes bytea;
  v_code text;
  v_made int := 0;
  v_inserted text;
begin
  if not public.has_role('admin') then
    raise exception 'admin_only' using errcode = '42501';
  end if;

  if create_invite_codes.count is null
     or create_invite_codes.count not between 1 and 100 then
    raise exception 'invalid_count'
      using errcode = '22023', detail = 'count must be between 1 and 100.';
  end if;

  while v_made < create_invite_codes.count loop
    v_bytes := extensions.gen_random_bytes(12);
    v_code := '';
    for i in 0..11 loop
      v_code := v_code || substr(c_alphabet, (get_byte(v_bytes, i) % 32) + 1, 1);
    end loop;

    -- On the (very unlikely) collision with an existing code, try again
    insert into public.invite_codes (code, kind, created_by)
    values (v_code, 'one_time', auth.uid())
    on conflict (code) do nothing
    returning code into v_inserted;

    if v_inserted is not null then
      v_made := v_made + 1;
      return next v_inserted;
      v_inserted := null;
    end if;
  end loop;

  return;
end;
$$;

-- Admin only. Revokes an unused one-time code. Revoking an already revoked
-- code does nothing. The master code cannot be revoked, only changed.
create function public.revoke_invite_code(code text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invite public.invite_codes%rowtype;
begin
  if not public.has_role('admin') then
    raise exception 'admin_only' using errcode = '42501';
  end if;

  select * into v_invite
    from public.invite_codes ic
   where ic.code = revoke_invite_code.code
   for update;

  if not found then
    raise exception 'code_not_found' using errcode = 'P0002';
  end if;
  if v_invite.kind = 'master' then
    raise exception 'cannot_revoke_master' using errcode = '22023';
  end if;
  if v_invite.used_at is not null then
    raise exception 'code_already_used' using errcode = '22023';
  end if;

  update public.invite_codes
     set revoked = true
   where id = v_invite.id;
end;
$$;

-- Admin only. Sets the master code, creating the row if none exists. The
-- old value stops working at once because the row is changed in place.
create function public.set_master_code(new_code text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.has_role('admin') then
    raise exception 'admin_only' using errcode = '42501';
  end if;

  if set_master_code.new_code is null
     or char_length(set_master_code.new_code) not between 8 and 64
     or set_master_code.new_code <> btrim(set_master_code.new_code) then
    raise exception 'invalid_master_code'
      using errcode = '22023',
            detail = 'The master code must be 8 to 64 characters with no leading or trailing spaces.';
  end if;

  if exists (
    select 1 from public.invite_codes ic
     where ic.code = set_master_code.new_code and ic.kind = 'one_time'
  ) then
    raise exception 'code_in_use' using errcode = '23505';
  end if;

  update public.invite_codes
     set code = set_master_code.new_code,
         created_by = auth.uid()
   where kind = 'master';

  if not found then
    insert into public.invite_codes (code, kind, created_by)
    values (set_master_code.new_code, 'master', auth.uid());
  end if;
end;
$$;

-- Supabase grants execute on new functions to anon by default; these are
-- for signed-in users only (and refuse non-Admins inside).
revoke execute on function public.create_invite_codes(int) from public, anon;
revoke execute on function public.revoke_invite_code(text) from public, anon;
revoke execute on function public.set_master_code(text) from public, anon;
grant execute on function public.create_invite_codes(int) to authenticated, service_role;
grant execute on function public.revoke_invite_code(text) to authenticated, service_role;
grant execute on function public.set_master_code(text) to authenticated, service_role;
